package com.abdickers.realms;

import android.content.Context;
import java.net.URI;
import java.util.*;
import org.json.*;

final class ToolLinks {
 record Link(String id,String title,String url,int icon){}
 static String safe(String raw){try{URI u=URI.create(raw.trim());if(!"https".equalsIgnoreCase(u.getScheme())||u.getHost()==null||u.getRawUserInfo()!=null||u.getPort()!=-1||u.getHost().equals("localhost")||u.getHost().matches("[0-9.]+")||u.getHost().endsWith(".local"))throw new Exception();return u.toASCIIString();}catch(Exception e){throw new IllegalArgumentException("Use a complete public HTTPS address without a username or password.");}}
 static int icon(String raw){String h=URI.create(raw).getHost().toLowerCase(Locale.ROOT);if(h.endsWith(".google.com")||h.equals("gemini.google.com")){if(h.startsWith("mail."))return R.drawable.brand_gmail;if(h.startsWith("calendar."))return R.drawable.brand_calendar;if(h.startsWith("drive."))return R.drawable.brand_drive;if(h.startsWith("gemini."))return R.drawable.brand_gemini;return R.drawable.elven_tools;}if(domain(h,"github.com"))return R.drawable.brand_github;if(domain(h,"slack.com"))return R.drawable.brand_slack;if(domain(h,"atlassian.net")||domain(h,"atlassian.com"))return raw.contains("/wiki")?R.drawable.brand_confluence:R.drawable.brand_jira;if(domain(h,"cloudflare.com"))return R.drawable.brand_cloudflare;if(domain(h,"vercel.com"))return R.drawable.brand_vercel;if(domain(h,"integrator.io"))return R.drawable.brand_celigo;if(domain(h,"netsuite.com"))return R.drawable.brand_netsuite;if(domain(h,"bigcommerce.com"))return R.drawable.brand_bigcommerce;if(domain(h,"chatgpt.com")||domain(h,"openai.com"))return R.drawable.brand_openai;if(domain(h,"claude.ai"))return R.drawable.brand_claude;if(domain(h,"zoom.us"))return R.drawable.brand_zoom;if(domain(h,"dotdigital.com"))return R.drawable.brand_dotdigital;if(domain(h,"avalara.com"))return R.drawable.brand_avalara;if(domain(h,"cybersource.com"))return R.drawable.brand_cybersource;if(domain(h,"netlify.com"))return R.drawable.brand_netlify;return R.drawable.icon_overview;}
 private static boolean domain(String host,String expected){return host.equals(expected)||host.endsWith("."+expected);}
 static List<Link> all(Context c,String realm){List<Link> links=new ArrayList<>();if(realm.equals("work")){
  String[][] defaults={{"NetSuite","https://system.netsuite.com/"},{"Celigo","https://integrator.io/"},{"Gmail","https://mail.google.com/mail/?authuser=dickersona%4076fireworks.com"},{"Calendar","https://calendar.google.com/calendar/r?authuser=dickersona%4076fireworks.com"},{"GitHub","https://github.com/abdickers"},{"Slack","https://76fireworks.slack.com/"},{"Jira","https://76fireworks.atlassian.net/"},{"Confluence","https://76fireworks.atlassian.net/wiki/"},{"BigCommerce","https://login.bigcommerce.com/"},{"Vercel","https://vercel.com/spirit-of-76-fireworks"},{"Cloudflare","https://dash.cloudflare.com/"},{"Drive","https://drive.google.com/?authuser=dickersona%4076fireworks.com"},{"ChatGPT","https://chatgpt.com/"},{"Claude","https://claude.ai/"},{"Gemini","https://gemini.google.com/"},{"Zoom","https://zoom.us/"},{"Dotdigital","https://login.dotdigital.com/"},{"Avalara","https://admin.avalara.com/"},{"Cybersource","https://businesscenter.cybersource.com/"},{"Netlify","https://app.netlify.com/"}};
  for(String[] item:defaults)links.add(new Link(item[0],item[0],item[1],icon(item[1])));
 }
 try{JSONArray a=new JSONArray(c.getSharedPreferences("boards",0).getString(realm+".links","[]"));for(int i=0;i<Math.min(a.length(),40);i++){JSONObject x=a.getJSONObject(i);String url=safe(x.getString("url"));links.add(new Link(x.getString("id"),x.getString("title"),url,icon(url)));}JSONObject overrides=new JSONObject(c.getSharedPreferences("boards",0).getString(realm+".link_overrides","{}"));List<Link> visible=new ArrayList<>();for(Link link:links){JSONObject edit=overrides.optJSONObject(link.id);if(edit!=null&&edit.optBoolean("hidden"))continue;String title=edit==null?link.title:edit.optString("title",link.title),url=edit==null?link.url:safe(edit.optString("url",link.url));visible.add(new Link(link.id,title,url,icon(url)));}return visible;}catch(JSONException e){throw new IllegalStateException("Saved links could not be read.");}}
 static synchronized void edit(Context c,String realm,String id,String title,String raw,boolean hidden){if(all(c,realm).stream().noneMatch(l->l.id.equals(id)))throw new IllegalArgumentException("This link is no longer available.");title=title.trim();if(title.isEmpty()||title.length()>100)throw new IllegalArgumentException("Enter a link name up to 100 characters.");String url=safe(raw);try{JSONObject overrides=new JSONObject(c.getSharedPreferences("boards",0).getString(realm+".link_overrides","{}"));overrides.put(id,new JSONObject().put("title",title).put("url",url).put("hidden",hidden));if(!c.getSharedPreferences("boards",0).edit().putString(realm+".link_overrides",overrides.toString()).commit())throw new IllegalStateException("The link could not be saved.");}catch(JSONException e){throw new IllegalStateException("Saved links could not be read.");}}
 static void restoreHidden(Context c,String realm){try{JSONObject overrides=new JSONObject(c.getSharedPreferences("boards",0).getString(realm+".link_overrides","{}"));for(Iterator<String> keys=overrides.keys();keys.hasNext();)overrides.getJSONObject(keys.next()).put("hidden",false);if(!c.getSharedPreferences("boards",0).edit().putString(realm+".link_overrides",overrides.toString()).commit())throw new IllegalStateException("Links could not be restored.");}catch(JSONException e){throw new IllegalStateException("Saved links could not be read.");}}
 static synchronized void add(Context c,String realm,String title,String raw){String url=safe(raw);title=title.trim();if(title.isEmpty()||title.length()>100)throw new IllegalArgumentException("Enter a link name up to 100 characters.");try{JSONArray a=new JSONArray(c.getSharedPreferences("boards",0).getString(realm+".links","[]"));if(a.length()>=40)throw new IllegalArgumentException("There are already 40 custom links.");a.put(new JSONObject().put("id",UUID.randomUUID().toString()).put("title",title).put("url",url));if(!c.getSharedPreferences("boards",0).edit().putString(realm+".links",a.toString()).commit())throw new IllegalStateException("The link could not be saved.");}catch(JSONException e){throw new IllegalStateException("The link could not be saved.");}}
 static List<FeedStore.Row> rows(Context c,String realm){List<FeedStore.Row> rows=new ArrayList<>();for(Link l:all(c,realm))rows.add(new FeedStore.Row(l.title,"Open tool ↗",l.icon,l.id));return rows;}
 private ToolLinks(){}
}
